const f = 'src/components/contact-form.kay'
let s = await Bun.file(f).text()
s = s.replace("import { contact } from '../routes/contact.kay'", "import { ActionError } from 'kay'\nimport { contact } from '../routes/contact.kay'")
s = s.replace(`  if (Object.keys(found).length === 0) {
    thanked.set((await contact(fields, { refresh: false })).name)
    form.reset()
  }`, `  if (Object.keys(found).length > 0)
    return

  try {
    thanked.set((await contact(fields, { refresh: false })).name)
    form.reset()
  }
  catch (error) {
    if (!(error instanceof ActionError) || !contact.refused(error))
      throw error
    errors.set(error.data?.errors ?? {})
  }`)
await Bun.write(f, s)
EOF
